package com.bankpli.javabank.account;
import com.bankpli.javabank.config.BankProperties;import com.bankpli.javabank.customer.CustomerRepository;import com.bankpli.javabank.shared.BusinessException;import java.math.*;import java.util.concurrent.atomic.AtomicLong;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class AccountService {private static final AtomicLong SEQUENCE=new AtomicLong(1000000000L);private final AccountRepository accounts;private final CustomerRepository customers;private final BankProperties properties;public AccountService(AccountRepository a,CustomerRepository c,BankProperties p){accounts=a;customers=c;properties=p;}public Account create(AccountRequest r){if(r.customerId()==null||!customers.existsById(r.customerId()))throw new BusinessException(HttpStatus.BAD_REQUEST,"Customer not found");if(r.type()==null)throw new BusinessException(HttpStatus.BAD_REQUEST,"Account type is required");BigDecimal opening=nvl(r.openingBalance()),limit=nvl(r.overdraftLimit()),rate=nvl(r.interestRate());if(opening.signum()<0||limit.signum()<0||rate.signum()<0)throw new BusinessException(HttpStatus.BAD_REQUEST,"Account amounts and rate must be non-negative");return accounts.save(new Account(r.customerId(),String.valueOf(SEQUENCE.incrementAndGet()),properties.systemSortCode(),r.type(),opening,limit,rate));}public Account get(long id){return accounts.findById(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Account not found"));}public Account find(String number,String sort){return accounts.findByAccountNumberAndSortCode(number,sort).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Account not found"));}public Account deactivate(long id){Account a=get(id);a.deactivate();return a;}public Account addHolder(long id,long customerId){if(!customers.existsById(customerId))throw new BusinessException(HttpStatus.BAD_REQUEST,"Customer not found");Account a=get(id);a.addHolder(customerId);return a;}public Account removeHolder(long id,long customerId){Account a=get(id);try{a.removeHolder(customerId);}catch(IllegalStateException e){throw new BusinessException(HttpStatus.CONFLICT,e.getMessage());}return a;}private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}}
